n0:createOraclePackageBody.n0:source:
CREATE OR REPLACE EDITIONABLE PACKAGE BODY "%USER_NAME%"."TOOLS" AS
    function client_original_assessment_date(p_case_number in number) return date
    as
        l_assessment_date date;
    begin
        select min(assessment_date)
        into l_assessment_date
        from clients
            join assessment using (case_number)
        where case_number = p_case_number;

        return l_assessment_date;
    exception
        when others then
            return null;
    end;

    function client_therapist_id(p_case_number in number) return number
    as
        l_therapist_id number;
    begin
        select therapist_id
        into l_therapist_id
        from clients
        where case_number = p_case_number;

        return l_therapist_id;
    exception
        when others then
            return null;
    end;
END TOOLS;
/
